 private boolean enabled(){for(InputMethodInfo info:((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).getEnabledInputMethodList())if(info.getPackageName().equals(getPackageName()))return true;return false;}
 @Override protected void onResume(){super.onResume();SyncJob.schedule(this);if(status!=null){boolean selected=String.valueOf(Settings.Secure.getString(getContentResolver(),Settings.Secure.DEFAULT_INPUT_METHOD)).startsWith(getPackageName()+"/");status.setText(selected?"当前正在使用":enabled()?"键盘已启用":"键盘尚未启用");Button button=(Button)content.findViewWithTag("activate");button.setText(enabled()?"切换键盘":"启用键盘");}}
 private LinearLayout section(String title){if(title!=null){TextView label=text(title,13,Ui.muted(this));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(dp(4),dp(22),0,dp(8));content.addView(label,lp);}LinearLayout box=new LinearLayout(this);box.setOrientation(1);Ui.panel(box);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);if(title==null)lp.topMargin=dp(16);content.addView(box,lp);return box;}
 private TextView row(LinearLayout box,String title,String detail,Runnable action){LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(dp(16),0,dp(16),0);line.addView(text(title,16,Ui.text(this)),new LinearLayout.LayoutParams(0,-2,1));TextView value=text(detail,14,Ui.muted(this));value.setTag("value");line.addView(value);TextView arrow=text("  ›",23,Ui.muted(this));line.addView(arrow);Ui.pressable(line,Ui.surface(this),12);line.setOnClickListener(v->action.run());box.addView(line,new LinearLayout.LayoutParams(-1,dp(54)));return value;}
 private String feedbackLabel(){String value=prefs.getString("feedback","light");return value.equals("off")?"关闭":value.equals("strong")?"强":"轻";}
 private void choice(String title,String[] labels,int selected,java.util.function.IntConsumer action){RadioGroup group=new RadioGroup(this);group.setPadding(dp(12),dp(2),dp(12),dp(8));for(int i=0;i<labels.length;i++){RadioButton radio=new RadioButton(this);radio.setId(2000+i);radio.setText(labels[i]);radio.setTextSize(17);radio.setTextColor(Ui.text(this));radio.setPadding(dp(12),0,dp(12),0);group.addView(radio,new RadioGroup.LayoutParams(-1,dp(52)));}group.check(2000+selected);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(group).setNegativeButton("取消",null).create();group.setOnCheckedChangeListener((v,id)->{if(id>=2000&&id<2000+labels.length){action.accept(id-2000);dialog.dismiss();}});Ui.dialog(dialog);}
 private void chooseLayout(){choice("中文布局",new String[]{"九宫格","26 键"},prefs.getBoolean("nine",true)?0:1,index->{prefs.edit().putBoolean("nine",index==0).apply();layoutValue.setText(index==0?"九宫格":"26 键");});}
 private void choosePosition(){choice("拼音显示位置",new String[]{"键盘内","文本框内"},prefs.getBoolean("inline",false)?1:0,index->{prefs.edit().putBoolean("inline",index==1).apply();inlineValue.setText(index==1?"文本框内":"键盘内");});}
 private void chooseFeedback(){String current=prefs.getString("feedback","light");String[] values={"off","light","strong"};choice("按键触感",new String[]{"关闭","轻","强"},current.equals("off")?0:current.equals("strong")?2:1,index->{prefs.edit().putString("feedback",values[index]).apply();feedbackValue.setText(feedbackLabel());});}
 private void heightDialog(){LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(18),dp(12),dp(18),dp(8));TextView value=text(prefs.getInt("height",58)+"",20,Ui.text(this));value.setGravity(Gravity.CENTER);body.addView(value);SeekBar slider=new SeekBar(this);slider.setMax(30);slider.setProgress(prefs.getInt("height",58)-46);body.addView(slider,new LinearLayout.LayoutParams(-1,dp(52)));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int n,boolean user){value.setText(String.valueOf(n+46));}});Ui.dialog(new AlertDialog.Builder(this).setTitle("键盘高度").setView(body).setNegativeButton("取消",null).setPositiveButton("完成",(d,w)->{int n=46+slider.getProgress();prefs.edit().putInt("height",n).apply();heightValue.setText(String.valueOf(n));}).create());}
 private void symbolsDialog(){LinearLayout body=new LinearLayout(this);body.setPadding(dp(18),0,dp(18),0);String[] defaults={"，","。","！","？"};EditText[] values=new EditText[4];for(int i=0;i<4;i++){values[i]=new EditText(this);values[i].setSingleLine();values[i].setText(prefs.getString("rail"+i,defaults[i]));body.addView(values[i],new LinearLayout.LayoutParams(0,dp(56),1));}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("常用符号").setView(body).setNegativeButton("取消",null).setPositiveButton("完成",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{android.content.SharedPreferences.Editor edit=prefs.edit();for(int i=0;i<4;i++){String text=values[i].getText().toString().trim();if(text.isEmpty()||text.codePointCount(0,text.length())>4){values[i].setError("请输入 1–4 个字符");return;}edit.putString("rail"+i,text);}edit.apply();dialog.dismiss();}));Ui.dialog(dialog);}
